def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    # Count opponent defections / recent defection rate.
    opp_defects = 0
    recent_opp_d = 0
    for i, (m, o) in enumerate(history):
        if o == 'D':
            opp_defects += 1
            if i >= n - 8:
                recent_opp_d += 1

    window = 8 if n >= 8 else n
    defect_rate_recent = recent_opp_d / window if window else 0.0

    # Persistent defector: defect to lock in 1 instead of losing 0.
    if opp_defects == n:
        return 'D'

    # If opponent is mostly defecting recently, defect.
    if recent_opp_d >= 6:
        return 'D'

    # Opponent just defected.
    if opp_last == 'D':
        # Forgive a one-off defection against an otherwise cooperative opponent,
        # but only occasionally so we don't get farmed.
        if opp_defects <= 2 and n >= 6 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # Opponent just cooperated.
    # If opponent rarely defects, maintain cooperation.
    if opp_defects <= 1:
        # Late-game mild exploitation of a pure cooperator.
        if n >= 95 and opp_defects == 0 and rng.random() < 0.4:
            return 'D'
        return 'C'

    # Opponent has defected a few times but is cooperating now.
    # Return to cooperation to re-establish CC, but avoid getting exploited.
    if defect_rate_recent <= 0.25:
        return 'C'

    # Mixed opponent: cooperate with high probability, defect to probe.
    if rng.random() < 0.2:
        return 'D'
    return 'C'
